 void planMemberships(SyncContext<Parameters> c){var p=c.parameters();var source=new ArrayList<MembershipInput>();for(var raw:p.memberships){var a=p.legacy.get(raw.userId);if(a==null||!includes(a.username))continue;String from=RoleCodes.T_SOURCE_CODES.get(raw.roleId.toString());var role=Objects.toString(RoleCodes.T_CODES.get(from),null);if(role==null)fail("MEMBERSHIP_ROLE_UNMAPPED");source.add(new MembershipInput("T:"+raw.id,a,role));}for(var a:p.accounts)if(a.fnd&&includes(a.username))for(var role:roles(a))source.add(new MembershipInput("FND:"+a.id+":"+role,a,role));
  var current=mapper.selectMemberships(new TenantQuery(c.tenantId(),c.preview()));var bindings=bindings(new BindingRead(c,"MEMBERSHIP",source.stream().map(MembershipInput::key).toList()));var planned=new HashMap<String,MembershipRow>();
  for(var input:source){var user=p.users.get(input.account.kind()+":"+input.account.id);var role=p.rolesByCode.get(input.role);if(user==null||role==null)fail("MEMBERSHIP_FOUNDATION_MISSING");String key=user.user.username+":"+input.role;var binding=bindings.get(input.key);var old=current.stream().filter(r->user.user.id!=null&&role.role.id!=null&&Objects.equals(r.userId,user.user.id)&&Objects.equals(r.roleId,role.role.id)&&!Boolean.TRUE.equals(r.deleted)).toList();if(old.size()>1)fail("FORMAL_MEMBERSHIP_AMBIGUOUS");var row=old.isEmpty()?planned.get(key):old.getFirst();var s=new Source();s.kind="MEMBERSHIP";s.key=input.key;s.action=SyncWriteAction.UNCHANGED;
   if(row==null){if(binding!=null)fail("BOUND_MEMBERSHIP_MISSING");row=new MembershipRow();row.id=c.preview()?null:IdWorker.getId();row.tenantId=c.tenantId();row.userId=user.user.id;row.roleId=role.role.id;row.creator=Long.toString(c.actorId());row.updater=row.creator;row.createTime=c.startedAt().withNano(0);row.updateTime=row.createTime;row.deleted=false;planned.put(key,row);s.action=SyncWriteAction.INSERT;}else if(binding!=null){if(row.id==null||binding.targetId()!=row.id||!binding.fingerprint().equals(membershipFingerprint(row)))fail("MEMBERSHIP_PROTECTED");s.previous=binding.fingerprint();}s.membership=row;p.plannedMemberships.add(s);
  }
 }
 record MembershipInput(String key,Account account,String role){}
 static Set<String> roles(Account a){var out=new TreeSet<String>();if(a.roleIds!=null)for(var id:a.roleIds.split("[;,]",-1)){if(id.isEmpty())continue;if(!id.matches("[1-9][0-9]*"))fail("ROLE_IDS_FORMAT_UNKNOWN");if(id.equals("15"))continue;var source=Objects.toString(RoleCodes.FND_CODES.get(id),null);if(source==null)fail("FND_ROLE_UNMAPPED");out.add(RoleCodes.targetFnd(source));}return out;}
 void planScopes(SyncContext<Parameters> c){var p=c.parameters();var scopes=new ArrayList<ScopeInput>();for(var group:p.names.entrySet()){if(group.getKey().equals("konglinghui_supp"))continue;var aliases=group.getValue();var fnd=primary(group.getKey(),aliases);if(!fnd.fnd)fnd=null;var legacy=aliases.stream().filter(a->!a.fnd).findFirst().orElse(null);var sourceRoles=legacy==null?List.<RawMembership>of():p.memberships.stream().filter(r->Objects.equals(r.userId,legacy.id)).toList();var companies=new TreeSet<String>();for(var r:sourceRoles)if(r.companyId!=null)companies.add(company(new CompanyResolution(r.companyId,p)).code);if(legacy!=null&&companies.isEmpty()&&ROLE_ONLY.contains(legacy.username))continue;
   if(fnd!=null){if(legacy==null)companies.addAll(List.of("001","002"));else if(companies.isEmpty())fail("CROSS_SOURCE_COMPANY_SCOPE_MISSING");for(var a:aliases)if(a.fnd){var roleCodes=roles(a);if(roleCodes.isEmpty())fail("SCOPE_ROLES_EMPTY");String own=office(a.dpNo);boolean primary=own!=null&&own.equals(office(fnd.dpNo));for(var role:roleCodes)for(var company:companies)scopes.add(new ScopeInput("FND:"+a.id+":OWN:"+company+":"+own+":"+role,a,company,own,role,primary,a.effectiveFrom==null?a.createTime:a.effectiveFrom,a.effectiveTo,a.creator,a.createTime,a.updater,a.updateTime));for(var power:p.powers)if(Objects.equals(power.fndUserId,a.id))for(var dep:offices(power.areapower))for(var role:roleCodes)for(var company:companies)scopes.add(new ScopeInput("POWER:"+power.id+":EXTRA:"+company+":"+dep+":"+role,a,company,dep,role,false,power.effectiveFrom==null?power.createTime:power.effectiveFrom,power.effectiveTo,power.creator,power.createTime,power.updater,power.updateTime));}}
   if(legacy!=null)for(var info:p.details.getOrDefault(legacy.id,List.of()))for(var relation:sourceRoles){if(relation.companyId==null)continue;String company=company(new CompanyResolution(relation.companyId,p)).code;String role=Objects.toString(RoleCodes.T_CODES.get(RoleCodes.T_SOURCE_CODES.get(relation.roleId.toString())),null);if(role==null)fail("SCOPE_ROLE_UNMAPPED");String own=office(info.custom3);boolean primary=own!=null&&(fnd==null||own.equals(office(fnd.dpNo)));scopes.add(new ScopeInput("INFO:"+info.id+":OWN:"+company+":"+own+":"+role,legacy,company,own,role,primary,legacy.createTime,null,legacy.creator,legacy.createTime,legacy.updater,legacy.updateTime));for(var dep:offices(info.custom5))scopes.add(new ScopeInput("INFO:"+info.id+":EXTRA:"+company+":"+dep+":"+role,legacy,company,dep,role,false,legacy.createTime,null,legacy.creator,legacy.createTime,legacy.updater,legacy.updateTime));}
  }
  if(scopes.size()>c.maxRows())fail("SCOPE_CAPACITY");var bindings=bindings(new BindingRead(c,"SCOPE",scopes.stream().map(ScopeInput::key).toList()));var current=mapper.selectScopes(new TenantQuery(c.tenantId(),c.preview()));var planned=new HashMap<String,ScopeRow>();var sourceKeys=new HashSet<String>();
  for(var input:scopes){if(!sourceKeys.add(input.key))continue;var user=p.users.get(input.account.kind()+":"+input.account.id);var company=p.directory.get("COMPANY:"+input.companyCode);var department=input.departmentCode==null?null:p.directory.get("DEPARTMENT:"+input.departmentCode);if(user==null||company==null||input.departmentCode!=null&&department==null)fail("FORMAL_SCOPE_REFERENCE_MISSING:"+input.departmentCode);var row=new ScopeRow();row.tenantId=c.tenantId();row.userId=user.user.id;row.companyId=company.id;row.companyCode=company.code;row.companyName=company.name;row.departmentId=department==null?null:department.id;row.departmentCode=department==null?null:department.code;row.departmentName=department==null?null:department.name;row.scopeRole=input.role;row.isPrimary=input.primary;row.effectiveFrom=input.from;row.effectiveTo=input.to;row.status=status(input.account);row.version=0L;row.creator=actor(new Actor(input.account,input.creator,p));row.updater=actor(new Actor(input.account,input.updater,p));row.createTime=input.created;row.updateTime=input.updated==null?input.created:input.updated;row.deleted=false;if(row.effectiveFrom==null||row.createTime==null||row.effectiveTo!=null&&row.effectiveTo.isBefore(row.effectiveFrom))fail("SCOPE_AUDIT_OR_INTERVAL_INVALID");validateScope(row);var binding=bindings.get(input.key);String business=SyncFingerprint.of(Arrays.asList(user.user.username,row.companyCode,row.departmentCode,row.scopeRole,row.isPrimary,row.effectiveFrom,row.effectiveTo,row.status,row.creator,row.createTime,row.updater,row.updateTime));var same=planned.get(business);var s=new Source();s.kind="SCOPE";s.key=input.key;s.action=SyncWriteAction.INSERT;
   if(binding!=null){var old=current.stream().filter(r->Objects.equals(r.id,binding.targetId())).findFirst().orElse(null);if(old==null||!binding.fingerprint().equals(scopeFingerprint(old)))fail("EXISTING_SCOPE_PROTECTED");row.id=old.id;row.version=old.version;if(!scopeFingerprint(old).equals(scopeFingerprint(row)))fail("SCOPE_HISTORY_CHANGED");s.previous=binding.fingerprint();s.action=SyncWriteAction.UNCHANGED;}
   else if(same!=null){row=same;s.action=SyncWriteAction.UNCHANGED;}
   else{var incoming=row;if(row.userId!=null&&current.stream().anyMatch(r->sameScope(r,incoming)))fail("UNOWNED_SCOPE_PROTECTED");row.id=c.preview()?null:IdWorker.getId();}s.scope=row;planned.putIfAbsent(business,row);p.plannedScopes.add(s);
  }
 }
 record ScopeInput(String key,Account account,String companyCode,String departmentCode,String role,boolean primary,LocalDateTime from,LocalDateTime to,String creator,LocalDateTime created,String updater,LocalDateTime updated){}
 static boolean sameScope(ScopeRow a,ScopeRow b){return Objects.equals(a.userId,b.userId)&&Objects.equals(a.companyId,b.companyId)&&Objects.equals(a.departmentId,b.departmentId)&&Objects.equals(a.scopeRole,b.scopeRole)&&Objects.equals(a.effectiveFrom,b.effectiveFrom);}
 static String office(String raw){if(raw==null||raw.isBlank())return null;return raw.matches("31120[2-9]|311210")?"1621"+raw.substring(4):raw;}
 static Set<String> offices(String raw){var out=new TreeSet<String>();if(raw!=null)for(var v:raw.split("[;,]"))if(!v.isBlank())out.add(office(v.trim()));return out;}

 @Override protected List<Source> syncDataQuery(SyncContext<Parameters> c){return new ArrayList<>(switch(c.dataName()){case "User"->c.parameters().plannedUsers;case "Role"->c.parameters().plannedRoles;case "Membership"->c.parameters().plannedMemberships;case "Scope"->c.parameters().plannedScopes;default->throw new IllegalArgumentException("P04_UNKNOWN_PHASE");});}
 @Override protected SyncCounts syncDataCount(SyncBatch<Source,Parameters> b){return SyncCounts.fromActions(b.rows(),Source::getAction);}
 @Override protected void syncDataInsert(SyncBatch<Source,Parameters> b){var fresh=b.matching(s->s.action==SyncWriteAction.INSERT);if(b.context().dataName().equals("User"))for(var s:fresh.rows())s.user.initialPasswordHash=passwords.encode(UUID.randomUUID().toString()+UUID.randomUUID());super.syncDataInsert(fresh);super.syncDataUpdate(b.matching(s->s.action==SyncWriteAction.UPDATE));if(b.context().dataName().equals("User")){var posts=new ArrayList<PostRow>();for(var s:fresh.rows())for(var id:s.posts){var row=new PostRow();row.id=IdWorker.getId();row.tenantId=b.context().tenantId();row.userId=s.user.id;row.postId=id;row.creator=s.user.creator;row.updater=s.user.updater;row.createTime=s.user.createTime;row.updateTime=s.user.updateTime;row.deleted=false;posts.add(row);}if(!posts.isEmpty()&&mapper.insertPosts(new PostsWrite(posts))!=posts.size())fail("POST_INSERT_CONFLICT");}}
 @Override protected void syncDataInsertAfter(SyncBatch<Source,Parameters> b){var saves=new ArrayList<SyncIdentityStore.Save>();for(var s:b.rows()){
  if(s.user!=null){if(s.action!=SyncWriteAction.UNCHANGED)saves.add(new SyncIdentityStore.Save("ACCOUNT",s.key,s.user.id,userFingerprint(s.user),s.previous));s.user.initialPasswordHash=null;for(var a:s.accounts)saves.add(new SyncIdentityStore.Save(a.kind(),a.id.toString(),s.user.id,SyncFingerprint.of(Arrays.asList(a.kind(),a.id,s.user.username,s.user.id)),s.aliasPrevious.get(a.kind()+":"+a.id)));}
  else if(s.role!=null)saves.add(new SyncIdentityStore.Save("ROLE",s.key,s.role.id,roleFingerprint(s.role),s.previous));
  else if(s.membership!=null)saves.add(new SyncIdentityStore.Save("MEMBERSHIP",s.key,s.membership.id,membershipFingerprint(s.membership),s.previous));else saves.add(new SyncIdentityStore.Save("SCOPE",s.key,s.scope.id,scopeFingerprint(s.scope),s.previous));
 }b.context().identities().saveAll(saves);}
 @Override protected void syncDataAfter(SyncContext<Parameters> c){if(c.dataName().equals("Role")||c.dataName().equals("Membership")){String name=c.dataName().equals("Role")?cn.iocoder.yudao.module.system.dal.redis.RedisKeyConstants.ROLE:cn.iocoder.yudao.module.system.dal.redis.RedisKeyConstants.USER_ROLE_ID_LIST;var cache=caches.getCache(name);if(cache!=null)org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCommit(){cache.clear();}});}}
